5}, {"conceptUuid": "44444444-0000-4000-8000-000000000038", "title": "OUTER JOIN", "summary": "짝이 없는 행도 버리지 않고, 모자란 쪽 열을 NULL로 채워 남겨요", "status": "NOT_STARTED", "checkCorrectCount": 0, "checkQuestionCount": 5}, {"conceptUuid": "44444444-0000-4000-8000-000000000039", "title": "CROSS JOIN", "summary": "조건 없이 두 표의 행을 모든 경우로 짝지어 M × N 행을 만들어요", "status": "NOT_STARTED", "checkCorrectCount": 0, "checkQuestionCount": 5}, {"conceptUuid": "44444444-0000-4000-8000-000000000040", "title": "셀프 조인", "summary": "같은 표를 별칭 두 개로 두 번 읽어, 사원과 관리자를 짝지어요", "status": "NOT_STARTED", "checkCorrectCount": 0, "checkQuestionCount": 5}]}, "33333333-0000-4000-8000-000000000006": {"topicUuid": "33333333-0000-4000-8000-000000000006", "displayName": "서브쿼리", "isLocked": false, "concepts": [{"conceptUuid": "44444444-0000-4000-8000-000000000041", "title": "단일행·다중행 서브쿼리", "summary": "서브쿼리가 돌려주는 행 수에 따라 함께 쓸 연산자가 달라져요", "status": "NOT_STARTED", "checkCorrectCount": 0, "checkQuestionCount": 5}, {"conceptUuid": "44444444-0000-4000-8000-000000000042", "title": "다중 컬럼 서브쿼리", "summary": "열 두 개 이상을 괄호로 묶어 한 번에 비교하는 서브쿼리예요", "status": "NOT_STARTED", "checkCorrectCount": 0, "checkQuestionCount": 5}, {"conceptUuid": "44444444-0000-4000-8000-000000000043", "title": "연관 서브쿼리와 EXISTS", "summary": "메인 쿼리의 행마다 다시 계산되는 서브쿼리이고, EXISTS는 행이 있는지만 봐요", "status": "NOT_STARTED", "checkCorrectCount": 0, "checkQuestionCount": 5}, {"conceptUuid": "44444444-0000-4000-8000-000000000044", "title": "스칼라 서브쿼리와 인라인 뷰", "summary": "SELECT 절에서 값 하나를 가져오는 서브쿼리와 FROM 절에서 표처럼 쓰는 서브쿼리예요", "status": "NOT_STARTED", "checkCorrectCount": 0, "checkQuestionCount": 5}, {"conceptUuid": "44444444-0000-4000-8000-000000000045", "title": "뷰", "summary": "SELECT 문에 이름을 붙여 저장해 두고 테이블처럼 쓰는 가상 테이블이에요", "status": "NOT_STARTED", "checkCorrectCount": 0, "checkQuestionCount": 5}, {"conceptUuid": "44444444-0000-4000-8000-000000000046", "title": "집합 연산자", "summary": "두 SELECT 결과를 위아래로 합치거나, 겹치는 행이나 빼고 남은 행을 구해요", "status": "NOT_STARTED", "checkCorrectCount": 0, "checkQuestionCount": 5}]}, "33333333-0000-4000-8000-000000000007": {"topicUuid": "33333333-0000-4000-8000-000000000007", "displayName": "그룹함수 / 집계", "isLocked": false, "concepts": [{"conceptUuid": "44444444-0000-4000-8000-000000000047", "title": "집계 함수와 NULL", "summary": "여러 행을 값 하나로 줄이는 함수이고, NULL인 행은 빼고 계산해요", "status": "NOT_STARTED", "checkCorrectCount": 0, "checkQuestionCount": 5}, {"conceptUuid": "44444444-0000-4000-8000-000000000048", "title": "GROUP BY와 HAVING", "summary": "같은 값을 가진 행끼리 묶어 집계하고, 묶은 결과를 HAVING으로 걸러요", "status": "NOT_STARTED", "checkCorrectCount": 0, "checkQuestionCount": 5}, {"conceptUuid": "44444444-0000-4000-8000-000000000049", "title": "ROLLUP", "summary": "묶음 기준을 오른쪽부터 하나씩 빼면서 소계와 총계를 붙여요", "status": "NOT_STARTED", "checkCorrectCount": 0, "checkQuestionCount": 5}, {"conceptUuid": "44444444-0000-4000-8000-000000000050", "title": "CUBE", "summary": "묶음 기준으로 만들 수 있는 모든 조합을 집계해요", "status": "NOT_STARTED", "checkCorrectCount": 0, "checkQuestionCount": 5}, {"conceptUuid": "44444444-0000-4000-8000-000000000051", "title": "GROUPING SETS", "summary": "필요한 묶음 기준만 골라 적어서 한 번에 집계해요", "status": "NOT_STARTED", "checkCorrectCount": 0, "checkQuestionCount": 5}, {"conceptUuid": "44444444-0000-4000-8000-000000000052", "title": "GROUPING 함수", "summary": "소계와 총계 때문에 생긴 NULL이면 1, 아니면 0을 돌려줘요", "status": "NOT_STARTED", "checkCorrectCount": 0, "checkQuestionCount": 5}]}, "33333333-0000-4000-8000-000000000008": {"topicUuid": "33333333-0000-4000-8000-000000000008", "displayName": "윈도우 함수", "isLocked": false, "concepts": [{"conceptUuid": "44444444-0000-4000-8000-000000000053", "title": "윈도우 함수 문법", "summary": "행을 줄이지 않고, 각 행 옆에 묶음별 계산값을 붙이는 함수예요", "status": "NOT_STARTED", "checkCorrectCount": 0, "checkQuestionCount": 5}, {"conceptUuid": "44444444-0000-4000-8000-000000000054", "title": "순위 함수", "summary": "RANK·​DENSE_RANK·​ROW_NUMBER는 동점을 다루는 방식이 달라요", "status": "NOT_STARTED", "checkCorrectCount": 0, "checkQuestionCount": 5}, {"conceptUuid": "44444444-0000-4000-8000-000000000055", "title": "집계 윈도우 함수", "summary": "SUM·​AVG 같은 집계 함수에 OVER를 붙여 합계·누적·이동 평균을 구해요", "status": "NOT_STARTED", "checkCorrectCount": 0, "checkQuestionCount": 5}, {"conceptUuid": "44444444-0000-4000-8000-000000000056", "title": "행 순서 함수", "summary": "범위의 첫 값·끝 값이나, 몇 칸 앞뒤 행의 값을 가져와요", "status": "NOT_STARTED", "checkCorrectCount": 0, "checkQuestionCount": 5}, {"conceptUuid": "44444444-0000-4000-8000-000000000057", "title": "비율 함수", "summary": "합계 대비 비율, 백분위 순위, 누적 비율, 그룹 번호를 구해요", "status": "NOT_STARTED", "checkCorrectCount": 0, "checkQuestionCount": 5}, {"conceptUuid": "44444444-0000-4000-8000-000000000058", "title": "윈도우 함수로 TOP N", "summary": "인라인 뷰에서 순위를 매기고 바깥에서 걸러, 부서별 상위 N명을 뽑아요", "status": "NOT_STARTED", "checkCorrectCount": 0, "checkQuestionCount": 5}]}, "33333333-0000-4000-8000-000000000009": {"topicUuid": "33333333-0000-4000-8000-000000000009", "displayName": "계층 / PIVOT", "isLocked": false, "concepts": [{"conceptUuid": "44444444-0000-4000-8000-000000000059", "title": "START WITH와 CONNECT BY", "summary": "시작 행을 고른 뒤 부모와 자식을 잇는 규칙을 따라 표를 나무 모양으로 펼쳐요", "status": "NOT_STARTED", "checkCorrectCount": 0, "checkQuestionCount": 5}, {"conceptUuid": "44444444-0000-4000-8000-000000000060", "title": "PRIOR 방향과 LEVEL", "summary": "PRIOR가 붙은 열은 이미 찾은 행이고, LEVEL은 몇 단계째인지 알려 줘요", "status": "NOT_STARTED", "checkCorrectCount": 0, "checkQuestionCount": 5}, {"conceptUuid": "44444444-0000-4000-8000-000000000061", "title": "계층 쿼리 함수와 정렬", "summary": "경로·루트·잎을 알려 주는 함수와, 계층 모양을 지키는 정렬을 다뤄요", "status": "NOT_STARTED", "checkCorrectCount": 0, "checkQuestionCount": 5}, {"conceptUuid": "44444444-0000-4000-8000-000000000062", "title": "PIVOT과 UNPIVOT", "summary": "PIVOT은 행의 값을 열로 세우고, UNPIVOT은 열을 다시 행으로 눕혀요", "status": "NOT_STARTED", "checkCorrectCount": 0, "checkQuestionCount": 5}, {"conceptUuid": "44444444-0000-4000-8000-000000000063", "title": "정규 표현식", "summary": "문자열의 모양을 기호로 적어서 찾고, 꺼내고, 바꾸는 방법이에요", "status": "NOT_STARTED", "checkCorrectCount": 0, "checkQuestionCount": 5}]}}, "detailByConcept": {"44444444-0000-4000-8000-000000000008": {"conceptUuid": "44444444-0000-4000-8000-000000000008", "topicUuid": "33333333-0000-4000-8000-000000000001", "title": "정규화", "summary": "같은 사실이 여러 곳에 적히지 않도록 테이블을 주제별로 나누는 과정이에요", "coreMd": "- 정규화는 섞여 있던 정보를 주제별로 나눠서 같은 사실이 여러 줄에 반복되지 않게 하는 과정이에요.\n- 순서는 1차 원자값 > 2차 부분 종속 제거 > 3차 이행 종속 제거 > BCNF 결정자가 모두 후보키예요(원부이결다조).\n- 2차는 기본키의 일부에 의존하는 칸을, 3차는 기본키가 아닌 칸에 의존하는 칸을 떼어 내요.\n- 기본키가 칸 하나면 부분 종속이 없어서, 1차 정규형만 만족해도 2차 정규형을 만족해요.\n- 이상 현상(삽입·삭제·갱신)은 줄지만, 조인이 늘어 조회는 오히려 느려질 수 있어요.", "detailSections": [{"anchor": "why", "title": "표 하나에 다 적으면 — 이상 현상 세 가지", "bodyMd": "학교 수강 신청을 표 하나에 모두 적으면 아래와 같아요. 겉보기에는 멀쩡하지만, 쓰다 보면 세 가지 문제가 생겨요.\n\n| 학번 | 이름 | 과목코드 | 과목명 | 성적 |\n|---|---|---|---|---|\n| 1 | 김민수 | DB01 | 데이터베이스 | A |\n| 1 | 김민수 | NW01 | 네트워크 | B |\n| 2 | 이지은 | DB01 | 데이터베이스 | B |\n\n| 외우기 | 뜻 |\n|---|---|\n| 삽 | 삽입(입력) 이상: 아직 아무도 신청하지 않은 새 과목은 학번 없이 줄을 만들 수 없어서 등록 자체가 안 돼요 |\n| 삭 | 삭제 이상: 네트워크를 듣는 유일한 학생인 김민수의 그 줄을 지우면 네트워크 과목 정보까지 사라져요 |\n| 갱 | 갱신(수정) 이상: 과목명을 바꾸려면 DB01 줄을 모두 고쳐야 하고, 하나라도 놓치면 같은 과목이 두 이름을 가져요 |\n\n정규화는 이런 이상 현상이 생기지 않도록 표를 주제별로 나누는 과정이에요."}, {"anchor": "dependency", "title": "함수 종속부터 — 어떤 칸이 어떤 칸을 정하나", "bodyMd": "정규화의 단계는 모두 \"어떤 칸이 어떤 칸에 의해 정해지는가\"로 설명돼요. 그래서 아래 용어부터 짚고 가면 뒤가 쉬워요.\n\n| 용어 | 뜻 |\n|---|---|\n| 함수 종속 (A → B) | A의 값을 알면 B의 값이 하나로 정해져요. 학번을 알면 이름이 정해지니 학번 → 이름이에요 |\n| 결정자 | 화살표 왼쪽의 A예요. 예: 학번 |\n| 종속자 | 화살표 오른쪽의 B예요. 예: 이름 |\n| 후보키 | 한 줄을 다른 줄과 구별할 수 있는 최소한의 칸 묶음이에요. 수강 표는 학번이나 과목코드 하나로는 안 되고, (학번, 과목코드)를 함께 봐야 구별돼요 |\n| 기본키 | 후보키가 여럿이면 그중 골라 줄을 대표로 구별하게 한 칸이에요 |\n| 부분 함수 종속 | 기본키 전체가 아니라 일부에만 의존해요. 기본키 (학번, 과목코드)에서 이름은 학번만 알아도 정해져요 |\n| 이행 함수 종속 | 한 다리 건너 의존해요. 학번 → 학과코드이고 학과코드 → 학과명이면 학과명은 학과코드를 거쳐 학번에 의존해요 |"}, {"anchor": "steps", "title": "단계별로 나누기 — 원부이결다조", "bodyMd": "| 외우기 | 뜻 |\n|---|---|\n| 원 | 1차 정규형: 칸 하나에 원자값(더 나눌 수 없는 값) 하나만 들어가게 해요 |\n| 부 | 2차 정규형: 부분 함수 종속을 없애요 |\n| 이 | 3차 정규형: 이행 함수 종속을 없애요 |\n| 결 | BCNF: 모든 결정자가 후보키가 되게 해요 |\n| 다 | 4차 정규형: 다치 종속(한 값에 여러 값 묶음이 서로 상관없이 딸려 오는 종속)을 없애요 |\n| 조 | 5차 정규형: 후보키를 거치지 않는 조인 종속을 없애요 |\n\n4차와 5차 정규형은 이 글에서 이름과 순서만 다뤄요. 1차부터 3차까지는 수강 표로 차례대로 나누면 아래와 같아요.\n\n| 단계 | 내용 |\n|---|---|\n| 1차 정규형 | 전화번호 칸에 \"010-1111, 010-2222\"처럼 두 값이 있으면, 줄을 나누거나 전화번호를 별도 테이블로 빼요 |\n| 2차 정규형 | 기본키 (학번, 과목코드)에서 이름은 학번에만, 과목명은 과목코드에만 의존하니 각각 떼어 내요 |\n| 3차 정규형 | 학생 테이블에 학과코드와 학과명이 함께 있으면, 학과명이 학과코드로 정해지니 학과(학과코드, 학과명)로 떼어 내요 |\n\n| 2차 정규형 뒤 테이블 | 칸 |\n|---|---|\n| 학생 | 학번(기본키), 이름 |\n| 과목 | 과목코드(기본키), 과목명 |\n| 수강 | 학번, 과목코드(합쳐서 기본키), 성적 |"}, {"anchor": "bcnf", "title": "BCNF — 결정자가 모두 후보키인가", "bodyMd": "BCNF는 이 규칙을 만든 두 학자 보이스(Boyce)와 코드(Codd)의 이름을 딴 정규형(Boyce-Codd Normal Form)이고, 3차 정규형보다 한 단계 엄격해요. 특강 신청(학번, 과목, 교수) 표에서 학생은 과목마다 교수 한 명에게 듣고, 교수 한 명은 한 과목만 가르쳐요.\n\n| 단계 | 내용 |\n|---|---|\n| 종속 적기 | 학번과 과목을 알면 교수가 정해지니 (학번, 과목) → 교수, 교수를 알면 과목이 정해지니 교수 → 과목이에요 |\n| 후보키 찾기 | (학번, 과목)과 (학번, 교수)는 둘 다 줄을 구별해서 후보키예요. 교수 하나로는 여러 학생의 줄이 있어 후보키가 아니에요 |\n| 결정자 확인 | 결정자는 (학번, 과목)과 교수인데, 교수는 결정자이면서 후보키가 아니라서 BCNF를 어겨요 |\n| 나누기 | (교수, 과목)과 (학번, 교수)로 나누면 두 표 모두 결정자가 후보키가 돼요 |\n\n나누기 전에는 교수가 맡는 과목을 바꿀 때 그 교수의 수강 줄을 모두 고쳐야 했어요. 나눈 뒤에는 (교수, 과목) 표의 한 줄만 고치면 돼요."}, {"anchor": "confusing", "title": "자주 헷갈리는 점", "bodyMd": "2차와 3차를 가장 많이 헷갈려요. 2차는 \"기본키의 일부\"에, 3차는 \"기본키가 아닌 칸\"에 의존하는 칸을 떼어 낸다고 기억해요.\n\n| 헷갈리는 말 | 실제로는 |\n|---|---|\n| 기본키가 한 칸인 테이블도 2차 정규형을 따로 검사해야 해요 | 기본키가 한 칸이면 일부라는 것이 없어 부분 종속이 생기지 않아요. 1차만 만족하면 2차도 만족해요 |\n| 정규화를 하면 조회가 항상 빨라져요 | 입력, 수정, 삭제는 단순해지지만 테이블이 나뉘어 조인이 늘고, 조회 성능이 떨어질 수 있어요 |\n| 3차 정규형을 만족하면 BCNF도 만족해요 | 특강 신청 표처럼 교수가 후보키에 들어가는 칸(과목)을 결정하면, 3차 검사는 통과하지만 BCNF는 위반이에요 |\n| 지웠더니 다른 정보까지 사라지는 것은 갱신 이상이에요 | 그것은 삭제 이상이에요. 여러 줄을 고쳐야 하면 갱신 이상, 다른 값이 없어 못 넣으면 삽입 이상이에요 |\n\n3차 정규형은 기본키가 아닌 칸이 다른 일반 칸을 결정하는 경우만 문제 삼아요. BCNF는 결정되는 칸이 무엇이든 결정자가 후보키가 아니면 나눠요.\n\n조인은 나뉜 테이블을 이어 붙여 읽는 일이에요. 조회가 아주 많은 곳에서는 일부러 다시 합치는 반정규화를 하기도 해요.\n\n| 바로 확인 | 정답 | 이유 |\n|---|---|---|\n| 이행 함수 종속을 없애는 단계는 3차 정규형이에요 | O | 원부이결다조에서 세 번째 글자가 이행의 '이'예요 |\n| BCNF는 3차 정규형보다 느슨한 규칙이에요 | X | BCNF는 3차 정규형보다 한 단계 엄격해요 |\n| 과목명이 과목코드에만 의존하면 기본키 (학번, 과목코드)에 대한 부분 종속이에요 | O | 기본키의 일부인 과목코드만 알아도 과목명이 정해져요 |"}, {"anchor": "exam-point", "title": "시험에서는 이렇게 나와요", "bodyMd": "가장 흔한 문제는 표와 함수 종속을 주고 몇 차 정규형을 위반했는지 묻는 것이고, 기본키부터 확인해서 일부에 의존하는 칸이 있으면 2차, 기본키가 아닌 칸에 의존하는 칸이 있으면 3차 위반이에요. 정규화의 효과를 묻는 문제에서는 \"조회 성능이 항상 좋아진다\"가 틀린 보기로 자주 나와요."}], "previousConceptUuid": "44444444-0000-4000-8000-000000000007", "nextConceptUuid": "44444444-0000-4000-8000-000000000009", "lastMode": "READ", "lastDepth": "CORE", "isRead": false, "checkCorrectCount": 0, "relatedQuestionUuids": ["22222222-0000-4000-8000-000000000001", "22222222-0000-4000-8000-000000000002", "22222222-0000-4000-8000-000000000003", "22222222-0000-4000-8000-000000000004", "22222222-0000-4000-8000-000000000005"]}, "44444444-0000-4000-8000-000000000014": {"conceptUuid": "44444444-0000-4000-8000-000000000014", "topicUuid": "33333333-0000-4000-8000-000000000002", "title": "관계형 데이터베이스와 SQL의 특징", "summary": "데이터를 표에 나눠 담는 데이터베이스와, 그 표를 다루는 SQL이에요", "coreMd": "- 관계형 데이터베이스는 데이터를 행과 열로 된 테이블에 담고, 기본키와 외래키로 테이블끼리 이어요.\n- SQL은 결과만 적고 처리 방법은 DBMS가 정하는 선언적(비절차적) 언어라서, \"절차적 언어\"는 틀린 보기예요.\n- DML은 SELECT·​INSERT·​UPDATE·​DELETE·​MERGE, DDL은 CREATE·​ALTER·​DROP·​RENAME·​TRUNCATE, DCL은 GRANT·​REVOKE, TCL은 COMMIT·​ROLLBACK·​SAVEPOINT예요.\n- 합집합·교집합·차집합·곱집합은 UNION·​INTERSECT·​MINUS·​CROSS JOIN에, 셀렉트는 WHERE에, 프로젝트는 SELECT 열 목록에 대응해요.\n- 디비전은 다른 테이블의 값을 모두 가진 쪽을 찾는 연산이고, SQL에는 대응하는 명령어가 없어요.", "detailSections": [{"anchor": "why", "title": "데이터베이스와 DBMS — 함께 쓰는 데이터를 한곳에", "bodyMd": "사원 명단을 직원마다 각자 파일로 들고 있으면, 누군가 급여를 고쳐도 다른 사람의 파일은 그대로라서 값이 금세 어긋나요. 그래서 여러 사람이 함께 쓰는 데이터는 한곳에 모아 두고, 그 일을 맡는 소프트웨어를 따로 둬요.\n\n| 용어 | 뜻 |\n|---|---|\n| 데이터베이스 | 여러 사람이 함께 쓰려고 한곳에 정리해 모아 둔 데이터 묶음이에요 |\n| DBMS | 데이터베이스 관리 시스템이에요. 데이터베이스를 만들고 데이터를 저장하고 찾고 고치며, 여러 사람의 동시 사용과 권한도 관리해요 |\n| Oracle, SQL Server | DBMS 제품의 이름이에요. SQLD는 주로 Oracle 기준으로 나오고, SQL Server와 다른 문법도 함께 물어요 |"}, {"anchor": "definition", "title": "관계형 데이터베이스 — 데이터를 표에 나눠 담아요", "bodyMd": "관계형 데이터베이스는 데이터를 칸이 나뉜 표, 곧 **테이블**에 담는 데이터베이스예요. 1970년에 E. F. Codd가 집합 이론을 바탕으로 제안한 관계형 모델에서 출발했고, 아래가 이 앱의 모든 예시에서 쓰는 사원 테이블과 부서 테이블이에요.\n\n| 사번 | 이름 | 직급 | 급여 | 부서번호 |\n|---|---|---|---|---|\n| 1001 | 김민수 | 사장 | 3000 | 10 |\n| 1002 | 이지은 | 과장 | 2500 | 20 |\n| 1003 | 박서준 | 대리 | 2800 | 20 |\n| 1004 | 최유나 | 부장 | 3200 | 30 |\n| 1005 | 정하늘 | 사원 | 2500 | 20 |\n| 1006 | 한도윤 | 대리 | 2700 | 30 |\n| 1007 | 오지민 | 사원 | 2200 | 30 |\n| 1008 | 윤서연 | 사원 | 2000 | NULL |\n\n| 부서번호 | 부서명 | 지역 |\n|---|---|---|\n| 10 | 기획부 | 서울 |\n| 20 | 개발부 | 판교 |\n| 30 | 영업부 | 부산 |\n| 40 | 인사부 | 서울 |\n\n| 흔히 부르는 말 | 관계형 모델 용어 | 사원 테이블에서 |\n|---|---|---|\n| 테이블 | 릴레이션 | 사원 테이블 전체 |\n| 행(로우), 가로 한 줄 | 튜플 | 김민수 한 사람의 정보 |\n| 열(컬럼), 세로 한 칸 | 속성(애트리뷰트) | 이름, 급여 같은 항목 |\n\n| 용어 | 뜻 |\n|---|---|\n| 차수 | 테이블의 열 개수예요. 부서 테이블은 열이 세 개라 차수가 3이에요 |\n| 카디널리티 | 테이블의 행 개수예요. 부서 테이블은 행이 네 개라 카디널리티가 4예요 |\n| 기본키 | 행 하나를 다른 행과 구별하는 열이에요. 사번, 부서번호처럼 같은 값이 두 번 들어갈 수 없고 비워 둘(NULL) 수도 없어요 |\n| 외래키 | 다른 테이블의 기본키를 가리키는 열이에요. 사원의 부서번호에는 부서 테이블에 있는 값이나 NULL만 들어가요 |\n\n1단원에서 그린 엔터티는 테이블로, 인스턴스는 행으로, 속성은 열로 만들어져요. 부서가 정해지지 않은 윤서연은 부서번호를 NULL(값이 비어 있다는 표시)로 두었고, 없는 부서번호를 넣으면 외래키 때문에 오류가 나요.\n\n```sql\nINSERT INTO 사원 (사번, 이름, 부서번호) VALUES (1009, '강하준', 50);  -- 오류: 부서 테이블에 50번 부서가 없어요 (ORA-02291, 참조할 부모 키 없음)\nINSERT INTO 사원 (사번, 이름, 부서번호) VALUES (1009, '강하준', 40);  -- 40번 인사부는 있어서 들어가요\n```\n\nINSERT는 테이블에 행을 넣는 명령이고 3단원에서 다뤄요. 키를 정하는 방법은 1단원 식별자 개념에서 자세히 다뤄요."}, {"anchor": "sql-features", "title": "SQL의 특징 — 결과만 적고, 집합으로 처리해요", "bodyMd": "**SQL**(Structured Query Language, 구조적 질의 언어)은 관계형 데이터베이스에 일을 시키는 언어예요. 시험에 나오는 맞는 특징은 아래 세 가지예요.\n\n| 용어 | 뜻 |\n|---|---|\n| 선언적 언어 (비절차적 언어) | 원하는 결과만 적고, 어느 행부터 어떻게 찾을지는 DBMS가 정해요. 처리 순서를 한 단계씩 적는 C, Java는 절차적 언어예요 |\n| 집합 단위 처리 | 문장 하나가 조건에 맞는 행 전체를 한꺼번에 처리해서, 행마다 반복문을 쓰지 않아요 |\n| 표준 언어 | ANSI와 ISO가 정한 표준이라 Oracle과 SQL Server가 같은 기본 문법을 써요. 다만 Oracle의 ROWNUM, SQL Server의 TOP처럼 제품마다 덧붙인 문법도 있어요 |\n| 옵티마이저 | DBMS 안에서 처리 방법을 고르는 부품이에요 |\n\n아래 SQL은 보여 줄 열(SELECT), 읽을 테이블(FROM), 행을 고를 조건(WHERE)만 적었어요. SELECT 문의 생김새는 다음 개념에서 자세히 다뤄요.\n\n```sql\nSELECT 이름, 급여 FROM 사원 WHERE 부서번호 = 20;\n```\n\n| 이름 | 급여 |\n|---|---|\n| 이지은 | 2500 |\n| 박서준 | 2800 |\n| 정하늘 | 2500 |\n\nUPDATE(행의 값을 고치는 명령, 3단원) 한 문장은 20번 부서 세 명의 급여를 모두 100씩 올려요. 이것이 집합 단위 처리예요.\n\n```sql\nUPDATE 사원 SET 급여 = 급여 + 100 WHERE 부서번호 = 20;\nSELECT 이름, 급여 FROM 사원 WHERE 부서번호 = 20;\n```\n\n| 이름 | 급여 |\n|---|---|\n| 이지은 | 2600 |\n| 박서준 | 2900 |\n| 정하늘 | 2600 |"}, {"anchor": "sql-types", "title": "SQL 명령어의 종류 — DML·​DDL·​DCL·​TCL", "bodyMd": "| 종류 | 하는 일 | 명령어 |\n|---|---|---|\n| DML (데이터 조작어) | 행을 조회하고, 넣고, 고치고, 지워요 | SELECT, INSERT, UPDATE, DELETE, MERGE |\n| DDL (데이터 정의어) | 테이블 같은 구조를 만들고, 바꾸고, 없애요 | CREATE, ALTER, DROP, RENAME, TRUNCATE |\n| DCL (데이터 제어어) | 다른 사용자에게 권한을 주고 빼앗아요 | GRANT, REVOKE |\n| TCL (트랜잭션 제어어) | 지금까지 한 변경을 확정하거나 취소해요 | COMMIT, ROLLBACK, SAVEPOINT |\n\nSELECT는 읽기만 해서 **DQL**(데이터 질의어)로 따로 부르기도 하지만, SQLD에서는 보통 DML에 넣어요. 트랜잭션은 계좌 이체의 출금과 입금처럼 함께 성공하거나 함께 취소되어야 하는 변경 묶음이고, DDL·​DCL·​TCL은 3단원에서 자세히 다뤄요."}, {"anchor": "relational-algebra", "title": "관계대수 — 테이블을 넣으면 테이블이 나오는 연산", "bodyMd": "관계대수는 테이블을 넣으면 테이블이 나오는 연산들의 모음이고, SQL은 이 연산을 문장으로 쓰게 만든 언어예요. 집합 이론에서 가져온 **일반 집합 연산** 네 가지와, 관계형 모델을 위해 만든 **순수 관계 연산** 네 가지로 나뉘어요.\n\n| 분류 | 연산 | 기호 | 하는 일 | SQL |\n|---|---|---|---|---|\n| 일반 집합 연산 | 합집합 | ∪ | 두 테이블의 행을 합쳐요 | UNION |\n| 일반 집합 연산 | 교집합 | ∩ | 양쪽에 함께 있는 행만 남겨요 | INTERSECT |\n| 일반 집합 연산 | 차집합 | − | 앞 테이블에만 있는 행을 남겨요 | MINUS (표준은 EXCEPT) |\n| 일반 집합 연산 | 곱집합(카티션 곱) | × | 행을 모든 조합으로 이어 붙여요 | CROSS JOIN |\n| 순수 관계 연산 | 셀렉트 | σ | 조건에 맞는 행을 골라요 | WHERE |\n| 순수 관계 연산 | 프로젝트 | π | 원하는 열을 골라요 | SELECT의 열 목록 |\n| 순수 관계 연산 | 조인 | ⋈ | 공통 값으로 두 테이블을 이어요 | JOIN (5단원) |\n| 순수 관계 연산 | 디비전 | ÷ | 다른 테이블의 값을 모두 가진 쪽을 찾아요 | 대응하는 명령어 없음 |\n\n합집합, 교집합, 차집합은 행을 통째로 비교해서 두 쪽의 열 개수와 데이터 종류가 같아야 써요. 아래는 부서와 사원의 부서번호 열을 비교한 예시이고, 집합 연산자의 규칙은 6단원에서 다뤄요.\n\n```sql\nSELECT 부서번호 FROM 부서 UNION SELECT 부서번호 FROM 사원;      -- 합집합이에요\nSELECT 부서번호 FROM 부서 INTERSECT SELECT 부서번호 FROM 사원;  -- 교집합이에요\nSELECT 부서번호 FROM 부서 MINUS SELECT 부서번호 FROM 사원;      -- 차집합이에요\nSELECT COUNT(*) FROM 부서 CROSS JOIN 사원;                     -- 곱집합의 행 수는 32예요\n```\n\n| 연산 | 결과 |\n|---|---|\n| UNION | 10, 20, 30, 40, NULL (중복은 한 번만, NULL은 윤서연의 부서번호) |\n| INTERSECT | 10, 20, 30 |\n| MINUS | 40 (사원이 없는 인사부) |\n| CROSS JOIN | 부서 4개 × 사원 8명 = 32행 (COUNT(*)는 행 수를 세는 함수, 7단원) |\n\n디비전(나눗셈)은 한 테이블의 값을 빠짐없이 모두 가진 행을 찾아요. 아래 자격보유를 필수자격으로 나누면, SQLD와 정보처리기사를 둘 다 가진 사원만 남아요.\n\n| 사번 | 자격 |\n|---|---|\n| 1002 | SQLD |\n| 1002 | 정보처리기사 |\n| 1003 | SQLD |\n| 1005 | SQLD |\n| 1005 | 정보처리기사 |\n| 1005 | 빅데이터분석기사 |\n| 1006 | 정보처리기사 |\n\n| 자격 |\n|---|\n| SQLD |\n| 정보처리기사 |\n\n| 사번 | 디비전 결과 |\n|---|---|\n| 1002 | 남아요. 두 자격을 모두 가졌어요 |\n| 1003 | 빠져요. 정보처리기사가 없어요 |\n| 1005 | 남아요. 빅데이터분석기사를 더 가져도 필수 두 개를 모두 가졌어요 |\n| 1006 | 빠져요. SQLD가 없어요 |\n\nSQL에는 디비전 명령어가 없어서 \"이 사원이 갖지 않은 필수 자격이 하나도 없다\"처럼 부정을 두 번 겹쳐 써요. 이때 쓰는 NOT EXISTS는 6단원 연관 서브쿼리와 EXISTS 개념에서 다뤄요."}, {"anchor": "select-project", "title": "셀렉트와 프로젝트 — 행을 고르나, 열을 고르나", "bodyMd": "지역이 서울인 행만 고르는 첫 SQL은 셀렉트 연산이고, 지역 열만 고르는 두 번째 SQL은 프로젝트 연산이에요. `*`는 모든 열을 뜻해요.\n\n```sql\nSELECT * FROM 부서 WHERE 지역 = '서울';\n```\n\n| 부서번호 | 부서명 | 지역 |\n|---|---|---|\n| 10 | 기획부 | 서울 |\n| 40 | 인사부 | 서울 |\n\n```sql\nSELECT 지역 FROM 부서;\n```\n\n| 지역 |\n|---|\n| 서울 |\n| 판교 |\n| 부산 |\n| 서울 |\n\n관계대수의 테이블은 집합이라 프로젝트 결과에서 같은 행이 하나로 합쳐지지만, SQL은 위처럼 서울을 두 번 보여 줘요. 같은 결과를 얻으려면 중복을 지우는 DISTINCT를 붙이고, DISTINCT는 \"별칭과 DISTINCT\" 개념에서 다뤄요.\n\n```sql\nSELECT DISTINCT 지역 FROM 부서;   -- 중복된 서울이 하나로 합쳐져서 세 행이 나와요\n```"}, {"anchor": "confusing", "title": "자주 헷갈리는 점 — 이름이 비슷한 짝", "bodyMd": "`SELECT 이름, 급여 FROM 사원 WHERE 부서번호 = 20`을 나눠 보면, 이름이 같은 SELECT 절이 셀렉트 연산이 아니라는 것이 보여요.\n\n| SQL 부분 | 하는 일 | 관계대수 연산 |\n|---|---|---|\n| WHERE 부서번호 = 20 | 20번 부서 행만 골라요 | 셀렉트 |\n| SELECT 이름, 급여 | 이름과 급여 열만 골라요 | 프로젝트 |\n\n| 헷갈리는 말 | 실제로는 |\n|---|---|\n| 셀렉트 연산은 SELECT 절에 해당해요 | 셀렉트는 행을 고르는 WHERE 절이고, SELECT 절의 열 목록은 프로젝트예요 |\n| SQL의 SELECT도 프로젝트처럼 중복을 없애요 | SQL은 중복 행을 남기고, DISTINCT를 붙여야 하나로 합쳐요 |\n| CROSS JOIN은 JOIN이니 순수 관계 연산이에요 | 곱집합은 일반 집합 연산이에요. 순수 관계 연산은 셀렉트, 프로젝트, 조인, 디비전 네 가지예요 |\n| TRUNCATE는 행을 지우니 DML이에요 | 테이블을 처음 만든 상태로 되돌리는 구조 명령이라 DDL이에요. Oracle은 DDL을 실행하면 자동으로 COMMIT(변경 확정)해서 ROLLBACK할 수 없어요 |\n| DELETE도 TRUNCATE처럼 되돌릴 수 없어요 | DELETE는 DML이라 COMMIT 전이면 ROLLBACK으로 되돌려요 (3단원) |\n| COMMIT과 ROLLBACK은 DCL이에요 | 권한과 상관없이 변경을 확정하거나 취소하는 TCL이에요 |\n| GRANT와 REVOKE는 DDL이에요 | Oracle 공식 문서는 DDL에 묶기도 하지만, SQLD 시험은 DCL로 분류해요 |\n| RENAME은 이름만 바꾸니 DML이에요 | 구조를 바꾸는 명령이라 DDL이에요. MERGE는 행을 넣거나 고치니 DML이에요 |\n| 관계 차수와 테이블의 차수는 같은 말이에요 | 관계 차수는 1:1, 1:M처럼 몇 개와 이어지는지이고, 테이블의 차수는 열 개수예요 |\n| 실행 순서는 사용자가 적는 처리 절차예요 | 결과가 어떻게 정해지는지 설명하는 규칙이에요. DBMS는 데이터 양에 따라 방법을 바꿔도 결과는 같아요 |\n\n| 바로 확인 | 정답 | 이유 |\n|---|---|---|\n| 카디널리티는 테이블의 행 개수를 가리키는 말이에요 | O | 열 개수는 차수, 행 개수는 카디널리티예요 |\n| 외래키 열에는 NULL을 넣을 수 없어요 | X | 부서가 없는 윤서연처럼 외래키 열은 NULL로 둘 수 있어요 |\n| SAVEPOINT는 TCL에 속해요 | O | COMMIT, ROLLBACK과 함께 변경을 다루는 트랜잭션 제어어예요 |\n| 합집합은 열 개수가 달라도 쓸 수 있어요 | X | 행을 통째로 비교하므로 열 개수와 데이터 종류가 같아야 해요 |"}, {"anchor": "exam-point", "title": "시험에서는 이렇게 나와요", "bodyMd": "SQL의 특징으로 알맞지 않은 것을 고르는 문제에서는 선언적, 집합 단위, 구조적, 절차적 같은 말이 섞여 나오고 \"절차적\"이 틀린 보기예요. 명령어의 분류를 묻는 문제, 관계대수 연산과 SQL을 짝짓는 문제, 작은 표 두 개로 디비전 결과를 묻는 문제도 자주 나와요."}], "previousConceptUuid": null, "nextConceptUuid": "44444444-0000-4000-8000-000000000015", "lastMode": "READ", "lastDepth": "CORE", "isRead": false, "checkCorrectCount": 0, "relatedQuestionUuids": ["22222222-0000-4000-8000-000000000001", "22222222-0000-4000-8000-000000000002", "22222222-0000-4000-8000-000000000003", "22222222-0000-4000-8000-000000000004", "22222222-0000-4000-8000-000000000005"]}, "44444444-0000-4000-8000-000000000054": {"conceptUuid": "44444444-0000-4000-8000-000000000054", "topicUuid": "33333333-0000-4000-8000-000000000008", "title": "순위 함수", "summary": "RANK·​DENSE_RANK·​ROW_NUMBER는 동점을 다루는 방식이 달라요", "coreMd": "- RANK는 동점에 같은 순위를 주고, 동점인 행 수만큼 다음 순위를 건너뛰어요(1, 1, 3).\n- DENSE_RANK는 동점에 같은 순위를 주되, 다음 순위를 건너뛰지 않아요(1, 1, 2).\n- ROW_NUMBER는 동점이어도 서로 다른 번호를 주고(1, 2, 3), 동점끼리의 순서는 ORDER BY에 기준을 더 넣어야 정해져요.\n- 세 함수 모두 OVER 안에 ORDER BY가 꼭 있어야 하고, PARTITION BY를 넣으면 묶음마다 1부터 다시 매겨요.\n- Oracle은 NULL을 가장 큰 값으로 보므로, 내림차순 순위에서는 NULL이 1등이 돼요.", "detailSections": [{"anchor": "why", "title": "몇 등인지 붙이기 — 문제는 동점이에요", "bodyMd": "급여 순서로 줄 세우는 일은 ORDER BY로 충분하지만, 각 사원이 몇 등인지 숫자로 붙이려면 순위 함수가 필요해요. 이때 바로 부딪히는 문제가 동점이고, 동점을 어떻게 다룰지에 따라 쓰는 함수가 달라져요.\n\n순위를 매길 사원 여덟 명은 아래와 같아요. 부서번호 10은 기획부, 20은 개발부, 30은 영업부이고, 윤서연은 부서번호가 NULL이라 부서가 없어요.\n\n| 사번 | 이름 | 급여 | 커미션 | 부서번호 |\n|---|---|---|---|---|\n| 1001 | 김민수 | 3000 | NULL | 10 |\n| 1002 | 이지은 | 2500 | 300 | 20 |\n| 1003 | 박서준 | 2800 | 0 | 20 |\n| 1004 | 최유나 | 3200 | NULL | 30 |\n| 1005 | 정하늘 | 2500 | NULL | 20 |\n| 1006 | 한도윤 | 2700 | 500 | 30 |\n| 1007 | 오지민 | 2200 | 200 | 30 |\n| 1008 | 윤서연 | 2000 | NULL | NULL |\n\n개발부의 이지은과 정하늘은 급여가 2500으로 같아요. 이 두 사람에게 같은 등수를 줄지, 그다음 사람은 몇 등으로 할지가 이 개념의 전부예요."}, {"anchor": "definition", "title": "한 줄 정의 — 세 함수는 동점만 다르게 다뤄요", "bodyMd": "순위 함수는 OVER 안의 ORDER BY 순서대로 각 행에 순위 번호를 붙이는 윈도우 함수예요. 동점이 없으면 세 함수의 결과는 똑같아요.\n\n| 함수 | 동점의 순위 | 동점 다음 순위 | 외우는 숫자 | 급여 3000, 2500, 2500, 2000 |\n|---|---|---|---|---|\n| RANK | 같은 순위 | 동점 수만큼 건너뜀 | 1, 1, 3 | 1, 2, 2, 4 |\n| DENSE_RANK | 같은 순위 | 건너뛰지 않음 | 1, 1, 2 | 1, 2, 2, 3 |\n| ROW_NUMBER | 서로 다른 번호 | 이어서 매김 | 1, 2, 3 | 1, 2, 3, 4 |\n\nRANK는 금메달이 둘이면 은메달 없이 다음 사람이 동메달을 받는 것과 같아요. DENSE는 \"빽빽한\"이라는 뜻이라서, DENSE_RANK는 빈 번호 없이 촘촘하게 매긴다고 기억하면 돼요."}, {"anchor": "small-example", "title": "작은 예시 — 개발부 세 명", "bodyMd": "급여가 높은 사람이 1등이 되도록 `ORDER BY 급여 DESC`로 정렬하고, 세 함수를 함께 적용했어요.\n\n```sql\nSELECT 이름, 급여,\n       RANK() OVER (ORDER BY 급여 DESC) AS 랭크,\n       DENSE_RANK() OVER (ORDER BY 급여 DESC) AS 덴스랭크,\n       ROW_NUMBER() OVER (ORDER BY 급여 DESC, 사번) AS 행번호\nFROM 사원\nWHERE 부서번호 = 20\nORDER BY 급여 DESC, 사번;\n```\n\n| 이름 | 급여 | 랭크 | 덴스랭크 | 행번호 |\n|---|---|---|---|---|\n| 박서준 | 2800 | 1 | 1 | 1 |\n| 이지은 | 2500 | 2 | 2 | 2 |\n| 정하늘 | 2500 | 2 | 2 | 3 |\n\n이지은과 정하늘은 RANK와 DENSE_RANK에서 똑같이 2등이에요. ROW_NUMBER는 두 사람에게 2와 3을 나눠 주는데, 급여만으로는 누가 2번일지 정할 수 없어서 `사번`을 두 번째 정렬 기준으로 넣었어요.\n\n이 예시에서는 동점 뒤에 다른 사람이 없어서 RANK와 DENSE_RANK의 차이가 드러나지 않아요. 차이는 동점 다음 사람에게서 나타나요."}, {"anchor": "full-example", "title": "전체 사원으로 보기 — 동점 다음 사람에서 갈려요", "bodyMd": "```sql\nSELECT 이름, 급여,\n       RANK() OVER (ORDER BY 급여 DESC) AS 랭크,\n       DENSE_RANK() OVER (ORDER BY 급여 DESC) AS 덴스랭크,\n       ROW_NUMBER() OVER (ORDER BY 급여 DESC, 사번) AS 행번호\nFROM 사원\nORDER BY 급여 DESC, 사번;\n```\n\n| 이름 | 급여 | 랭크 | 덴스랭크 | 행번호 |\n|---|---|---|---|---|\n| 최유나 | 3200 | 1 | 1 | 1 |\n| 김민수 | 3000 | 2 | 2 | 2 |\n| 박서준 | 2800 | 3 | 3 | 3 |\n| 한도윤 | 2700 | 4 | 4 | 4 |\n| 이지은 | 2500 | 5 | 5 | 5 |\n| 정하늘 | 2500 | 5 | 5 | 6 |\n| 오지민 | 2200 | 7 | 6 | 7 |\n| 윤서연 | 2000 | 8 | 7 | 8 |\n\n| 확인할 곳 | RANK | DENSE_RANK |\n|---|---|---|\n| 동점 5등 다음인 오지민 | 6등을 비우고 7등 | 빈 번호 없이 6등 |\n| 가장 큰 순위 값 | 8, 맨 끝에 동점이 없으면 늘 전체 행 수 | 7, 서로 다른 급여가 일곱 가지라서 |\n\n| 바로 확인 | 정답 | 이유 |\n|---|---|---|\n| DENSE_RANK의 가장 큰 값은 서로 다른 정렬 값의 개수와 같아요 | O | 빈 번호 없이 값이 바뀔 때마다 하나씩 올라가요 |\n| RANK와 DENSE_RANK는 동점인 두 사람에게 서로 다른 순위를 줘요 | X | 두 함수 모두 동점에는 같은 순위를 주고, 다음 순위만 달라요 |"}, {"anchor": "partition", "title": "부서별 순위 — PARTITION BY면 1부터 다시", "bodyMd": "OVER 안에 PARTITION BY를 넣으면 묶음마다 순위를 따로 매기고, 묶음이 바뀌면 다시 1부터 시작해요.\n\n```sql\nSELECT 부서번호, 이름, 급여,\n       RANK() OVER (PARTITION BY 부서번호 ORDER BY 급여 DESC) AS 부서순위\nFROM 사원\nORDER BY 부서번호, 부서순위, 사번;\n```\n\n| 부서번호 | 이름 | 급여 | 부서순위 |\n|---|---|---|---|\n| 10 | 김민수 | 3000 | 1 |\n| 20 | 박서준 | 2800 | 1 |\n| 20 | 이지은 | 2500 | 2 |\n| 20 | 정하늘 | 2500 | 2 |\n| 30 | 최유나 | 3200 | 1 |\n| 30 | 한도윤 | 2700 | 2 |\n| 30 | 오지민 | 2200 | 3 |\n| NULL | 윤서연 | 2000 | 1 |\n\n개발부에서는 박서준이 1등이고, 이지은과 정하늘이 함께 2등이에요. 부서가 없는 윤서연은 NULL끼리 한 묶음이 되어 혼자 1등이 돼요.\n\n바깥의 `ORDER BY`는 결과를 보기 좋게 정렬할 뿐이에요. 순위 값은 OVER 안의 ORDER BY로 이미 정해져 있어요."}, {"anchor": "confusing", "title": "자주 헷갈리는 점", "bodyMd": "| 헷갈리는 말 | 실제로는 |\n|---|---|\n| DENSE_RANK는 동점 다음 순위를 건너뛰어요 | 건너뛰는 쪽은 RANK예요. 동점 바로 다음 사람의 번호가 동점 수만큼 비어 있으면 RANK, 비어 있지 않으면 DENSE_RANK예요 |\n| ROW_NUMBER는 동점이면 사번이 빠른 사람에게 앞 번호를 줘요 | ORDER BY 기준이 급여뿐이면 누가 앞 번호를 받을지는 Oracle이 정하고, 실행할 때마다 바뀔 수도 있어요. 고정하려면 ORDER BY 급여 DESC, 사번처럼 기준을 더 넣어요 |\n| 순위 함수의 OVER 괄호는 비워 둬도 돼요 | 무엇으로 줄 세울지 모르면 순위를 매길 수 없어서, ORDER BY를 빼면 ORA-30485(OVER 안에 ORDER BY가 없음) 오류가 나요. PARTITION BY는 생략할 수 있어요 |\n| RANK() OVER (ORDER BY 급여)는 급여가 높은 사람이 1등이에요 | OVER 안의 ORDER BY도 기본이 오름차순(ASC)이라서, 급여가 가장 낮은 윤서연이 1등이에요. 높은 값을 1등으로 하려면 DESC를 써요 |\n| NULL은 순위에서 빠지거나 맨 뒤로 가요 | Oracle은 정렬할 때 NULL을 가장 큰 값으로 봐요. 오름차순이면 맨 뒤, 내림차순이면 맨 앞에 와요 |\n\n```sql\n-- 오류: 순위 함수에 ORDER BY가 없어요 (ORA-30485)\nSELECT 이름, RANK() OVER () FROM 사원;\n```\n\n커미션으로 내림차순 순위를 매기면 커미션이 NULL인 네 명이 함께 1등이 되고, 커미션이 가장 많은 한도윤은 5등이 돼요. NULL을 뒤로 보내려면 정렬 기준 뒤에 `NULLS LAST`(NULL을 맨 뒤에 두라는 표시)를 붙여요.\n\n```sql\nSELECT 이름, 커미션,\n       RANK() OVER (ORDER BY 커미션 DESC) AS 기본,\n       RANK() OVER (ORDER BY 커미션 DESC NULLS LAST) AS 널뒤로\nFROM 사원\nORDER BY 기본, 사번;\n```\n\n| 이름 | 커미션 | 기본 | 널뒤로 |\n|---|---|---|---|\n| 김민수 | NULL | 1 | 5 |\n| 최유나 | NULL | 1 | 5 |\n| 정하늘 | NULL | 1 | 5 |\n| 윤서연 | NULL | 1 | 5 |\n| 한도윤 | 500 | 5 | 1 |\n| 이지은 | 300 | 6 | 2 |\n| 오지민 | 200 | 7 | 3 |\n| 박서준 | 0 | 8 | 4 |\n\n| 바로 확인 | 정답 | 이유 |\n|---|---|---|\n| PARTITION BY를 빼고 ORDER BY만 써도 순위 함수는 실행돼요 | O | PARTITION BY를 빼면 전체 행이 한 묶음이 될 뿐이에요 |\n| NULLS LAST를 붙이면 NULL인 행은 순위 계산에서 빠져요 | X | NULL인 행도 순위를 받고, 맨 뒤로 갈 뿐이에요 |"}, {"anchor": "exam-point", "title": "시험에서는 이렇게 나와요", "bodyMd": "세 함수를 함께 적용한 SQL을 주고, 결과 표에서 틀린 값을 찾거나 특정 사원의 순위를 묻는 문제가 가장 많아요. 동점인 행부터 찾아서 그 행과 바로 다음 행의 번호만 확인하면 대부분 풀려요.\n\n| 함께 확인할 것 | 보는 곳 |\n|---|---|\n| 묶음마다 다시 세는가 | OVER 안에 PARTITION BY가 있는지 |\n| 높은 값이 1등인가 | OVER 안의 ORDER BY가 DESC인지 |\n| NULL이 어디로 가는가 | 내림차순이면 맨 앞, NULLS LAST가 있으면 맨 뒤 |"}], "previousConceptUuid": "44444444-0000-4000-8000-000000000053", "nextConceptUuid": "44444444-0000-4000-8000-000000000055", "lastMode": "READ", "lastDepth": "CORE", "isRead": false, "checkCorrectCount": 0, "relatedQuestionUuids": ["22222222-0000-4000-8000-000000000001", "22222222-0000-4000-8000-000000000002", "22222222-0000-4000-8000-000000000003", "22222222-0000-4000-8000-000000000004", "22222222-0000-4000-8000-000000000005"]}}, "questionsByConcept": {"44444444-0000-4000-8000-000000000008": [{"questionUuid": "55555555-0000-4000-8000-000000000081", "sortOrder": 1, "stem": "학번을 알면 이름이 하나로 정해질 때, 이 관계를 바르게 나타낸 것은 무엇인가요?", "stemSql": null, "choices": [{"choiceKey": "A", "body": "이름 → 학번"}, {"choiceKey": "B", "body": "학번과 이름은 서로 관계가 없다"}, {"choiceKey": "C", "body": "학번 → 이름"}, {"choiceKey": "D", "body": "이름이 결정자이다"}]}, {"questionUuid": "55555555-0000-4000-8000-000000000082", "sortOrder": 2, "stem": "기본키가 (학번, 과목코드)인 수강 테이블에 학번만 알면 정해지는 '학생이름' 칸이 있어요. 어떤 정규형을 위반했나요?", "stemSql": null, "choices": [{"choiceKey": "A", "body": "1차 정규형"}, {"choiceKey": "B", "body": "2차 정규형"}, {"choiceKey": "C", "body": "3차 정규형"}, {"choiceKey": "D", "body": "BCNF"}]}, {"questionUuid": "55555555-0000-4000-8000-000000000083", "sortOrder": 3, "stem": "학생(학번 기본키, 학과코드, 학과명) 테이블에서 학과명은 학과코드에 의해 정해져요. 이 종속과 위반한 정규형을 바르게 짝지은 것은 무엇인가요?", "stemSql": null, "choices": [{"choiceKey": "A", "body": "부분 함수 종속, 2차 정규형"}, {"choiceKey": "B", "body": "이행 함수 종속, 3차 정규형"}, {"choiceKey": "C", "body": "부분 함수 종속, 3차 정규형"}, {"choiceKey": "D", "body": "이행 함수 종속, 2차 정규형"}]}, {"questionUuid": "55555555-0000-4000-8000-000000000084", "sortOrder": 4, "stem": "정규화에 대한 설명으로 옳지 않은 것은 무엇인가요?", "stemSql": null, "choices": [{"choiceKey": "A", "body": "같은 사실이 한 곳에만 있어서 수정 이상이 줄어든다"}, {"choiceKey": "B", "body": "테이블 수가 늘어날 수 있다"}, {"choiceKey": "C", "body": "정규화를 하면 조회 성능이 항상 좋아진다"}, {"choiceKey": "D", "body": "입력 이상과 삭제 이상을 줄인다"}]}, {"questionUuid": "55555555-0000-4000-8000-000000000085", "sortOrder": 5, "stem": "기본키가 칸 하나뿐이고 1차 정규형을 만족하는 테이블에 대해 바르게 말한 것은 무엇인가요?", "stemSql": null, "choices": [{"choiceKey": "A", "body": "이미 2차 정규형도 만족한다"}, {"choiceKey": "B", "body": "반드시 3차 정규형을 위반한다"}, {"choiceKey": "C", "body": "반드시 BCNF를 만족한다"}, {"choiceKey": "D", "body": "더 이상 정규화가 필요 없다"}]}], "44444444-0000-4000-8000-000000000014": [{"questionUuid": "55555555-0000-4000-8000-000000000141", "sortOrder": 1, "stem": "관계형 모델에서 테이블의 열(컬럼)을 부르는 말은 무엇인가요?", "stemSql": null, "choices": [{"choiceKey": "A", "body": "튜플"}, {"choiceKey": "B", "body": "릴레이션"}, {"choiceKey": "C", "body": "속성"}, {"choiceKey": "D", "body": "기본키"}]}, {"questionUuid": "55555555-0000-4000-8000-000000000142", "sortOrder": 2, "stem": "SQL 언어의 특징으로 알맞지 않은 것은 무엇인가요?", "stemSql": null, "choices": [{"choiceKey": "A", "body": "원하는 결과만 적고 처리 방법은 DBMS가 정하는 선언적 언어이다"}, {"choiceKey": "B", "body": "조건에 맞는 행을 집합 단위로 한꺼번에 처리한다"}, {"choiceKey": "C", "body": "관계형 데이터베이스의 표준 언어이다"}, {"choiceKey": "D", "body": "데이터를 처리하는 순서를 한 단계씩 적는 절차적 언어이다"}]}, {"questionUuid": "55555555-0000-4000-8000-000000000143", "sortOrder": 3, "stem": "SQL 명령어와 종류를 짝지은 것으로 알맞지 않은 것은 무엇인가요?", "stemSql": null, "choices": [{"choiceKey": "A", "body": "COMMIT - DCL"}, {"choiceKey": "B", "body": "TRUNCATE - DDL"}, {"choiceKey": "C", "body": "GRANT - DCL"}, {"choiceKey": "D", "body": "MERGE - DML"}]}, {"questionUuid": "55555555-0000-4000-8000-000000000144", "sortOrder": 4, "stem": "관계대수의 셀렉트 연산과 같은 일을 하는 SQL 부분은 무엇인가요?", "stemSql": null, "choices": [{"choiceKey": "A", "body": "SELECT 절의 열 목록"}, {"choiceKey": "B", "body": "WHERE 절"}, {"choiceKey": "C", "body": "CROSS JOIN"}, {"choiceKey": "D", "body": "MINUS"}]}, {"questionUuid": "55555555-0000-4000-8000-000000000145", "sortOrder": 5, "stem": "아래 자격보유 테이블을 필수자격 테이블로 나눈 디비전(÷) 결과로 알맞은 것은 무엇인가요?\n\n| 사번 | 자격 |\n|---|---|\n| 1002 | SQLD |\n| 1002 | 정보처리기사 |\n| 1003 | SQLD |\n| 1005 | SQLD |\n| 1005 | 정보처리기사 |\n| 1005 | 빅데이터분석기사 |\n| 1006 | 정보처리기사 |\n\n| 자격 |\n|---|\n| SQLD |\n| 정보처리기사 |", "stemSql": null, "choices": [{"choiceKey": "A", "body": "1003, 1006"}, {"choiceKey": "B", "body": "1002, 1003, 1005, 1006"}, {"choiceKey": "C", "body": "1002, 1005"}, {"choiceKey": "D", "body": "1002"}]}], "44444444-0000-4000-8000-000000000054": [{"questionUuid": "55555555-0000-4000-8000-000000000541", "sortOrder": 1, "stem": "동점인 행에 같은 순위를 주고, 그다음 순위를 동점인 행 수만큼 건너뛰는 함수는 무엇인가요?", "stemSql": null, "choices": [{"choiceKey": "A", "body": "ROW_NUMBER"}, {"choiceKey": "B", "body": "DENSE_RANK"}, {"choiceKey": "C", "body": "RANK"}, {"choiceKey": "D", "body": "세 함수 모두 같다"}]}, {"questionUuid": "55555555-0000-4000-8000-000000000542", "sortOrder": 2, "stem": "급여가 3000, 2500, 2500, 2000인 네 행에 `DENSE_RANK() OVER (ORDER BY 급여 DESC)`를 적용하면 순위는 어떻게 되나요?", "stemSql": null, "choices": [{"choiceKey": "A", "body": "1, 2, 2, 4"}, {"choiceKey": "B", "body": "1, 2, 2, 3"}, {"choiceKey": "C", "body": "1, 2, 3, 4"}, {"choiceKey": "D", "body": "1, 1, 2, 3"}]}, {"questionUuid": "55555555-0000-4000-8000-000000000543", "sortOrder": 3, "stem": "아래 사원 표에 다음 SQL을 실행하면 오지민(급여 2200)의 순위는 얼마인가요?\n\n| 사번 | 이름 | 급여 |\n|---|---|---|\n| 1001 | 김민수 | 3000 |\n| 1002 | 이지은 | 2500 |\n| 1003 | 박서준 | 2800 |\n| 1004 | 최유나 | 3200 |\n| 1005 | 정하늘 | 2500 |\n| 1006 | 한도윤 | 2700 |\n| 1007 | 오지민 | 2200 |\n| 1008 | 윤서연 | 2000 |", "stemSql": "SELECT 이름, RANK() OVER (ORDER BY 급여 DESC) AS 순위 FROM 사원;", "choices": [{"choiceKey": "A", "body": "6"}, {"choiceKey": "B", "body": "8"}, {"choiceKey": "C", "body": "5"}, {"choiceKey": "D", "body": "7"}]}, {"questionUuid": "55555555-0000-4000-8000-000000000544", "sortOrder": 4, "stem": "`ROW_NUMBER() OVER (ORDER BY 급여 DESC)`로 번호를 매길 때, 급여가 2500으로 같은 이지은과 정하늘에 대한 설명으로 옳은 것은 무엇인가요?", "stemSql": null, "choices": [{"choiceKey": "A", "body": "두 사람 모두 5번을 받는다"}, {"choiceKey": "B", "body": "사번이 빠른 이지은이 항상 5번을 받는다"}, {"choiceKey": "C", "body": "한 명은 5번, 다른 한 명은 6번이고, 누가 5번일지는 정해져 있지 않다"}, {"choiceKey": "D", "body": "두 사람 모두 6번을 받는다"}]}, {"questionUuid": "55555555-0000-4000-8000-000000000545", "sortOrder": 5, "stem": "20번 부서 사원은 이지은(급여 2500), 박서준(2800), 정하늘(2500) 세 명이에요. 다음 SQL의 결과로 옳은 것은 무엇인가요?", "stemSql": "SELECT 이름, DENSE_RANK() OVER (PARTITION BY 부서번호 ORDER BY 급여) AS 순위 FROM 사원 WHERE 부서번호 = 20;", "choices": [{"choiceKey": "A", "body": "이지은 1, 정하늘 1, 박서준 2"}, {"choiceKey": "B", "body": "이지은 1, 정하늘 1, 박서준 3"}, {"choiceKey": "C", "body": "박서준 1, 이지은 2, 정하늘 2"}, {"choiceKey": "D", "body": "이지은 1, 정하늘 2, 박서준 3"}]}]}, "answerKeyByQuestion": {"55555555-0000-4000-8000-000000000081": {"correctKey": "C", "explanation": "A를 알면 B가 하나로 정해질 때 A → B로 적어요. 학번을 알면 이름이 정해지므로 학번 → 이름이고, 학번이 결정자예요.", "rereadAnchor": "dependency", "rationaleByChoiceKey": {"A": "화살표 방향이 반대예요. 같은 이름의 학생이 여럿일 수 있어요.", "B": "학번이 이름을 정하므로 관계가 있어요.", "C": "학번이 결정자, 이름이 종속자예요.", "D": "결정자는 화살표 왼쪽의 학번이에요."}}, "55555555-0000-4000-8000-000000000082": {"correctKey": "B", "explanation": "학생이름이 기본키의 일부인 학번에만 의존하므로 부분 함수 종속이고, 이를 없애는 것은 2차 정규형이에요.", "rereadAnchor": "steps", "rationaleByChoiceKey": {"A": "칸마다 값이 하나씩이면 1차 정규형은 만족해요.", "B": "기본키의 일부에만 의존하는 부분 종속이에요.", "C": "3차는 기본키가 아닌 칸에 의존할 때예요.", "D": "그보다 앞 단계인 2차 정규형부터 위반이에요."}}, "55555555-0000-4000-8000-000000000083": {"correctKey": "B", "explanation": "학번 → 학과코드 → 학과명처럼 한 다리 건너 의존하므로 이행 함수 종속이고, 이를 없애는 것은 3차 정규형이에요.", "rereadAnchor": "dependency", "rationaleByChoiceKey": {"A": "기본키가 한 칸이라 부분 종속은 생기지 않아요.", "B": "기본키가 아닌 학과코드를 거쳐 의존해요.", "C": "종속의 이름이 틀렸어요.", "D": "이행 종속을 없애는 것은 3차 정규형이에요."}}, "55555555-0000-4000-8000-000000000084": {"correctKey": "C", "explanation": "정규화를 하면 테이블이 나뉘어 조회할 때 조인이 늘어나므로, 조회 성능은 오히려 떨어질 수 있어요.", "rereadAnchor": "confusing", "rationaleByChoiceKey": {"A": "정규화의 효과예요.", "B": "주제별로 나누므로 늘어날 수 있어요.", "C": "조인이 늘어 느려질 수 있어서 틀린 설명이에요.", "D": "정규화의 효과예요."}}, "55555555-0000-4000-8000-000000000085": {"correctKey": "A", "explanation": "부분 함수 종속은 기본키가 여러 칸일 때만 생겨요. 기본키가 한 칸이면 1차 정규형만 만족해도 2차 정규형을 만족해요.", "rereadAnchor": "confusing", "rationaleByChoiceKey": {"A": "기본키의 일부라는 것이 없어서 부분 종속이 생기지 않아요.", "B": "이행 종속이 있을 때만 위반해요.", "C": "BCNF는 결정자를 따로 확인해야 해요.", "D": "이행 종속이 있으면 3차 정규화가 필요해요."}}, "55555555-0000-4000-8000-000000000141": {"correctKey": "C", "explanation": "테이블은 릴레이션, 행은 튜플, 열은 속성(애트리뷰트)이라고 불러요. 기본키는 행을 구별하는 데 쓰는 열을 가리키는 말이에요.", "rereadAnchor": "definition", "rationaleByChoiceKey": {"A": "튜플은 가로 한 줄인 행을 부르는 말이에요.", "B": "릴레이션은 테이블 전체를 부르는 말이에요.", "C": "열 하나가 이름, 급여 같은 속성 하나에 해당해요.", "D": "기본키는 열 중에서 행을 구별하는 데 쓰는 특정한 열이에요."}}, "55555555-0000-4000-8000-000000000142": {"correctKey": "D", "explanation": "SQL은 원하는 결과만 적고 처리 방법은 DBMS가 정하는 선언적(비절차적) 언어예요. 처리 순서를 한 단계씩 적는 것은 절차적 언어의 특징이에요.", "rereadAnchor": "sql-features", "rationaleByChoiceKey": {"A": "SQL의 맞는 특징이에요.", "B": "문장 하나가 조건에 맞는 행 전체를 처리하므로 맞는 설명이에요.", "C": "ANSI와 ISO가 정한 표준 언어라서 맞는 설명이에요.", "D": "SQL은 절차를 적지 않는 비절차적 언어라서 틀린 설명이에요."}}, "55555555-0000-4000-8000-000000000143": {"correctKey": "A", "explanation": "COMMIT은 변경을 확정하는 트랜잭션 제어어(TCL)예요. 권한을 다루는 DCL에는 GRANT와 REVOKE가 들어가요.", "rereadAnchor": "sql-types", "rationaleByChoiceKey": {"A": "COMMIT은 TCL이라서 잘못 짝지었어요.", "B": "TRUNCATE는 테이블을 처음 상태로 되돌리는 DDL이에요.", "C": "권한을 주는 명령이라 DCL이 맞아요.", "D": "행을 넣거나 고치는 명령이라 DML이 맞아요."}}, "55555555-0000-4000-8000-000000000144": {"correctKey": "B", "explanation": "셀렉트 연산은 조건에 맞는 행을 고르는 연산이라 **WHERE 절**에 해당해요. SELECT 절의 열 목록은 열을 고르는 프로젝트 연산이에요.", "rereadAnchor": "confusing", "rationaleByChoiceKey": {"A": "열을 고르는 일은 프로젝트 연산이에요.", "B": "조건에 맞는 행만 남기는 일이 셀렉트 연산이에요.", "C": "모든 조합을 이어 붙이는 곱집합 연산이에요.", "D": "앞쪽에만 있는 행을 남기는 차집합 연산이에요."}}, "55555555-0000-4000-8000-000000000145": {"correctKey": "C", "explanation": "디비전은 필수자격의 SQLD와 정보처리기사를 빠짐없이 모두 가진 사번을 찾아요. 1002와 1005가 둘 다 가졌고, 1005가 다른 자격을 더 가진 것은 결과에 영향을 주지 않아요.", "rereadAnchor": "relational-algebra", "rationaleByChoiceKey": {"A": "필수 자격을 하나씩만 가진 사원이라 디비전 결과에서 빠져요.", "B": "자격을 하나라도 가진 사원을 모두 셌는데, 디비전은 전부 가진 쪽만 남겨요.", "C": "두 필수 자격을 모두 가진 사원은 1002와 1005예요.", "D": "필수 자격 외의 자격을 더 가져도 결과에서 빠지지 않아서 1005도 남아요."}}, "55555555-0000-4000-8000-000000000541": {"correctKey": "C", "explanation": "RANK는 동점에 같은 순위를 준 뒤 그 수만큼 번호를 비워요. DENSE_RANK는 비우지 않고, ROW_NUMBER는 동점에도 다른 번호를 줘요.", "rereadAnchor": "definition", "rationaleByChoiceKey": {"A": "ROW_NUMBER는 동점이어도 서로 다른 번호를 줘요.", "B": "DENSE_RANK는 동점 다음 순위를 건너뛰지 않아요.", "C": "동점에 같은 순위를 주고 다음 순위를 건너뛰어요.", "D": "세 함수는 동점을 처리하는 방식이 서로 달라요."}}, "55555555-0000-4000-8000-000000000542": {"correctKey": "B", "explanation": "DENSE_RANK는 2500 두 행에 같은 2등을 주고, 다음 행에 빈 번호 없이 3등을 줘요.", "rereadAnchor": "definition", "rationaleByChoiceKey": {"A": "다음 순위를 건너뛴 RANK의 결과예요.", "B": "동점 다음 순위를 건너뛰지 않아요.", "C": "동점에도 다른 번호를 준 ROW_NUMBER의 결과예요.", "D": "3000과 2500은 값이 달라서 같은 순위가 아니에요."}}, "55555555-0000-4000-8000-000000000543": {"correctKey": "D", "explanation": "이지은과 정하늘이 함께 5등이라서 RANK는 6등을 비워 둬요. 그래서 그다음인 오지민은 7등이에요.", "rereadAnchor": "full-example", "rationaleByChoiceKey": {"A": "번호를 건너뛰지 않는 DENSE_RANK의 결과예요.", "B": "오지민보다 급여가 낮은 윤서연이 8등이에요.", "C": "5등은 급여 2500인 이지은과 정하늘이에요.", "D": "동점 2명이 5등을 차지해서 6등이 비고, 오지민은 7등이에요."}}, "55555555-0000-4000-8000-000000000544": {"correctKey": "C", "explanation": "ROW_NUMBER는 동점이어도 서로 다른 번호를 줘요. 다만 급여만 기준이라서 둘 중 누가 앞 번호를 받을지는 정해져 있지 않아요.", "rereadAnchor": "confusing", "rationaleByChoiceKey": {"A": "같은 번호를 주는 것은 RANK와 DENSE_RANK예요.", "B": "ORDER BY에 사번이 없어서 사번 순서는 보장되지 않아요.", "C": "동점끼리의 순서는 ORDER BY에 기준을 더 넣어야 정해져요.", "D": "ROW_NUMBER는 같은 번호를 두 번 주지 않아요."}}, "55555555-0000-4000-8000-000000000545": {"correctKey": "A", "explanation": "오름차순이라 급여가 낮은 2500 두 명이 함께 1등이에요. DENSE_RANK는 번호를 건너뛰지 않으므로 박서준은 2등이에요.", "rereadAnchor": "partition", "rationaleByChoiceKey": {"A": "오름차순 DENSE_RANK의 결과예요.", "B": "다음 순위를 건너뛴 RANK의 결과예요.", "C": "DESC가 없으므로 급여가 낮은 쪽이 1등이에요.", "D": "동점에 다른 번호를 준 ROW_NUMBER의 결과예요."}}}}''';
